190	
191	  const view = (name: "release" | "contractual", definition: {text: string; anchor: Anchor}): View => {
192	    const included = rows.filter((row) => row.obligation.views.includes(name) || row.contra);
193	    const debt = included.reduce((sum, row) => sum.plus(row.balance), d(0));
194	    const cash = input.cash!;
195	    const operands: Record<string, string> = {debt: out(debt), cashAndEquivalents: cash.cashAndEquivalents.value, financialInvestments: cash.financialInvestments.value};
196	    const anchors: Record<string, Anchor> = {cashAndEquivalents: cash.cashAndEquivalents.anchor, financialInvestments: cash.financialInvestments.anchor};
197	    let value = debt.minus(cash.cashAndEquivalents.value).minus(cash.financialInvestments.value);
198	    let formula = "debt - cashAndEquivalents - financialInvestments";
199	    if (name === "contractual") {
200	      value = value.plus(cash.derivativeLiabilities.value).minus(cash.derivativeAssets.value);
201	      formula = "debt + derivativeLiabilities - derivativeAssets - cashAndEquivalents - financialInvestments";
202	      operands.derivativeLiabilities = cash.derivativeLiabilities.value; operands.derivativeAssets = cash.derivativeAssets.value;
203	      anchors.derivativeLiabilities = cash.derivativeLiabilities.anchor; anchors.derivativeAssets = cash.derivativeAssets.anchor;
204	    }
205	    calculations.push({id: "financial.debt_views", formula: `${name}: ${formula}`, operands, result: out(value)});
206	    return {value: out(value), definition: definition.text, definitionSource: definition.anchor, components: operands, componentAnchors: anchors, rowsIncluded: included.map((row) => row.id)};
207	  };
208	  let netDebtViews: DebtLedgerOutput["netDebtViews"] = {release: null, contractual: null, releaseReported: null};
209	  if (rows.length > 0) {
210	    if (!input.cash) incompleteReasons.push("no cash, investments and derivatives in the base: net debt views are not computed");
211	    else {
212	      if (input.definitions.release) netDebtViews.release = view("release", input.definitions.release);
213	      else incompleteReasons.push("no release definition with a source: the release view is not computed");
214	      if (input.definitions.contractual) netDebtViews.contractual = view("contractual", input.definitions.contractual);
215	      else incompleteReasons.push("no contractual definition with a source: the contractual view is not computed");
216	    }
217	    if (input.releaseReportedNetDebt) {
218	      const reported = d(input.releaseReportedNetDebt.value);
219	      netDebtViews.releaseReported = {value: out(reported), differenceToRelease: netDebtViews.release ? out(reported.minus(netDebtViews.release.value)) : null, anchor: input.releaseReportedNetDebt.anchor};
220	    }
221	  }
222	
223	  const group = (key: (row: Row) => string) => {
224	    const map = new Map<string, {balance: Decimal; rows: string[]}>();
225	    for (const row of rows) {
226	      if (row.contra) continue;
227	      const entry = map.get(key(row)) ?? {balance: d(0), rows: []};
228	      entry.balance = entry.balance.plus(row.balance);
229	      entry.rows.push(row.id);
230	      map.set(key(row), entry);
231	    }
232	    return [...map.entries()].sort(([a], [b]) => compare(a, b)).map(([label, entry]) => ({label, balance: out(entry.balance), shareOfGrossBeforeContra: share(entry.balance, grossBeforeContra), rows: entry.rows}));
233	  };
234	
235	  const uncoveredTerms: DebtLedgerOutput["uncoveredTerms"] = [];
236	  for (const row of rows) {
237	    if (row.contra) continue;
238	    const label = `${row.instrument}${row.series ? ` ${row.series}` : ""}`;
239	    if (row.remuneration === null) uncoveredTerms.push({rowId: row.id, field: "remuneration", state: "insufficient_evidence", reason: `no source in the base states the remuneration of ${label}; the currency is not an indexer`});
240	    if (row.maturity === null) uncoveredTerms.push({rowId: row.id, field: "maturity", state: "insufficient_evidence", reason: `no source in the base states the maturity of ${label}`});
241	    if (row.guarantee === null) uncoveredTerms.push({rowId: row.id, field: "guarantee", state: "insufficient_evidence", reason: `no source in the base states the guarantee of ${label}`});
242	    if (row.lender === null) uncoveredTerms.push({rowId: row.id, field: "lender", state: "insufficient_evidence", reason: `no source in the base states the holder of ${label}`});
243	    if (row.classification === null) uncoveredTerms.push({rowId: row.id, field: "classification", state: "insufficient_evidence", reason: `the note gives current and non-current totals, not the split of ${label}`});
244	  }
245	
246	  const state: DebtLedgerOutput["state"] = blockReasons.length > 0
247	    ? "blocked"
248	    : input.source === "release_only"
249	      ? "incomplete"
250	      : rows.length === 0
251	        ? "empty"
252	        : incompleteReasons.length > 0 ? "incomplete" : "complete";
253	  const body = {
254	    schemaVersion: "method.build-debt-ledger.v3" as const,
255	    referenceDate: input.referenceDate, priorDate: input.priorDate, unit: input.unit, source: input.source, state, blockReasons, incompleteReasons,
256	    ledgerRows: rows.map((row) => ({
257	      id: row.id, instrument: row.instrument, series: row.series ?? null, obligation: row.obligation, balance: out(d(row.balance)), priorBalance: row.priorBalance === null ? null : out(d(row.priorBalance)),
258	      currency: row.currency, remuneration: row.remuneration, maturity: row.maturity, guarantee: row.guarantee, lender: row.lender, classification: row.classification, contra: row.contra, anchors: row.anchors,
259	    })),
260	    grossDebt: out(gross), grossDebtPrior: grossPrior ? out(grossPrior) : null, grossDebtBeforeContra: out(grossBeforeContra),
261	    reconciliation, schedule, netDebtViews,
262	    byIndexer: group(indexerOf).map(({label, ...rest}) => ({indexer: label, ...rest})),
263	    byCurrency: group((row) => row.currency).map(({label, ...rest}) => ({currency: label, ...rest})),
264	    uncoveredTerms,
265	  };
266	  return {...body, trace: {calculations, inputFingerprint: fingerprint(input), outputFingerprint: fingerprint(body)}};
