 65	/** Deterministic permutation, different at every step. */
 66	const permute = <T>(items: T[], seed: number): T[] => {
 67	  const copy = [...items];
 68	  let state = seed;
 69	  for (let index = copy.length - 1; index > 0; index -= 1) {
 70	    state = (state * 1103515245 + 12345) % 2147483648;
 71	    const swap = state % (index + 1);
 72	    [copy[index], copy[swap]] = [copy[swap]!, copy[index]!];
 73	  }
 74	  return copy;
 75	};
